import java.util.List;

public class Main {

    enum Prop { REQUIRED, REQUIRES_NEW, NESTED, SUPPORTS, NOT_SUPPORTED, MANDATORY, NEVER }

    static class Tx {
        final int id;
        final java.util.List<String> ops = new java.util.ArrayList<>();
        final java.util.List<Integer> savepoints = new java.util.ArrayList<>();
        Tx(int id) { this.id = id; }
    }

    static class TxManager {
        final java.util.List<String> db = new java.util.ArrayList<>();
        int seq = 0;
        Tx current = null;

        Tx begin(Prop p) {
            switch (p) {
                case REQUIRED:
                    if (current != null) return current;
                    current = new Tx(++seq);
                    return current;
                case REQUIRES_NEW: {
                    current = new Tx(++seq);
                    return current;
                }
                case NESTED:
                    if (current != null) {
                        current.savepoints.add(current.ops.size());
                        System.out.println("savepoint sp" + current.savepoints.size()
                                + " at depth " + current.ops.size());
                        return current;
                    }
                    current = new Tx(++seq);
                    return current;
                case SUPPORTS:
                    return current;
                case NOT_SUPPORTED:
                    current = null;
                    return null;
                case MANDATORY:
                    if (current == null)
                        throw new IllegalStateException("No existing transaction found for MANDATORY");
                    return current;
                case NEVER:
                    if (current != null)
                        throw new IllegalStateException("Existing transaction found for NEVER");
                    return null;
                default:
                    return current;
            }
        }

        void op(String s) {
            if (current != null) current.ops.add(s);
            else db.add(s);
        }

        void commit(Tx t) {
            if (t == null) return;
            db.addAll(t.ops);
            if (current == t) current = null;
        }

        void rollback(Tx t) {
            if (current == t) current = null;
        }

        void rollbackToSavepoint(Tx t) {
            if (t == null || t.savepoints.isEmpty()) return;
            int mark = t.savepoints.remove(t.savepoints.size() - 1);
            while (t.ops.size() > mark) t.ops.remove(t.ops.size() - 1);
        }
    }

    static class BusinessException extends RuntimeException {
        BusinessException(String m) { super(m); }
    }
    static class CheckedException extends Exception {
        CheckedException(String m) { super(m); }
    }

    // 默认 rollbackFor=RuntimeException：仅运行时异常回滚
    static boolean runWith(Throwable t, boolean rollbackChecked) {
        TxManager tm = new TxManager();
        Tx tx = tm.begin(Prop.REQUIRED);
        tm.op("insert:order");
        boolean rollback = (t instanceof RuntimeException) || rollbackChecked;
        if (rollback) tm.rollback(tx);
        else tm.commit(tx);
        return tm.db.isEmpty();
    }

    public static void main(String[] args) {
        boolean a = runWith(new BusinessException("boom"), false);
        System.out.println("[A] RuntimeException (default rollbackFor) -> rolled back: " + a);

        boolean b = runWith(new CheckedException("io"), false);
        System.out.println("[B] checked Exception (default) -> rolled back: " + b);
        System.out.println("[B] => checked exception did NOT rollback, data committed: " + (!b));

        boolean c = runWith(new CheckedException("io"), true);
        System.out.println("[C] checked Exception + rollbackFor=Exception -> rolled back: " + c);
    }
}
